# 函數：鼠標按下時的位置
def win_start_move(event):
    root.x = event.x
    root.y = event.y


def win_stop_move(event):
    root.x = None
    root.y = None


def win_do_move(event):
    deltax = event.x - root.x
    deltay = event.y - root.y
    x = root.winfo_x() + deltax
    y = root.winfo_y() + deltay
    root.geometry(f"+{x}+{y}")


